{
  "name": "@johannus22/opencode-tps-meter",
  "version": "0.1.2",
  "description": "Live tokens-per-second meter with visual bar indicator for OpenCode TUI",
  "type": "module",
  "scripts": {
    "build": "tsc --pretty false",
    "typecheck": "tsc --noEmit --pretty false",
    "prepack": "npm run build",
    "prepublishOnly": "npm run build"
  },
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.jsx",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/index.jsx",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "opencode": ">=1.3.14"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*",
    "@opentui/core": "*",
    "@opentui/solid": "*",
    "solid-js": "*"
  },
  "keywords": [
    "opencode",
    "plugin",
    "tps",
    "tokens-per-second",
    "performance",
    "meter",
    "solid-js"
  ],
  "author": "jeyyy-arr",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/johannus22/opencode-tps.git"
  },
  "homepage": "https://github.com/johannus22/opencode-tps#readme",
  "bugs": {
    "url": "https://github.com/johannus22/opencode-tps/issues"
  },
  "devDependencies": {
    "typescript": "^5.8.2"
  }
}
